def recipe_conversion(recipe):
    """
    Converts a recipe between cups, tablespoons, and teaspoons.

    :param recipe: List of ingredients in the format ['1 cup', '2 tablespoons']
    :return: None
    """

    # Define conversion rules
    conversion_rules = {
        'cups': {
            'tablespoons': 1.5,
            'teaspoons': 16
        },
        'tablespoons': {
            'cups': 0.67,
            'teaspoons': 12
        },
        'teaspoons': {
            'cups': 0.067,
            'tablespoons': 3.5
        }
    }

    # Check if the input is a valid recipe
    if not recipe or not all(ingredient.isdigit() for ingredient in recipe):
        print("Invalid recipe format. Please enter a list of ingredients in the format ['1 cup', '2 tablespoons'].")
        return

    # Convert ingredients and print the result
    for ingredient in recipe:
        amount, unit = ingredient.strip().split()
        if unit not in conversion_rules:
            print(f"Invalid unit '{unit}'. Supported units are 'cups', 'tablespoons', and 'teaspoons'.")
            continue

        converted_amount = conversion_rules[unit][amount]
        print(f"{amount} {unit} is equivalent to {converted_amount} {conversion_rules[unit]['cups']}.")


# Example usage
recipe = ['1 cup', '2 tablespoons']
recipe_conversion(recipe)
```

This program checks if the input is a valid recipe, then converts the ingredients and prints the result. The conversion rules are defined in a dictionary, and the program checks if the input unit is supported before converting the amount.
